# BattleSim.gd —— 确定性战斗模拟核心（玩法文档 §2.0 §2.1）
# 纯逻辑无场景依赖：30 tick/s 固定步进、种子随机、整数伤害。
# UI 层（BattleScene）每渲染帧按速度倍率步进并消费 events。
class_name BattleSim
extends RefCounted

const TICK_RATE := 30
const MAX_TICKS := 30 * 300  # 5 分钟硬上限（防死循环）

var rng := RandomNumberGenerator.new()
var units: Array[Combatant] = []
var cast_queue: Array[Dictionary] = []
var last_cast: Dictionary = {}        # uid -> {skill_id, tick}
var tick_count: int = 0
var events: Array[Dictionary] = []    # UI 消费（headless 模拟可关）
var record_events := true
var finished := false
var result := ""                      # "" / "victory" / "defeat"
var auto_mode := false                # 托管
var manual_basic_attack := false      # 手动模式：非托管时主角普攻由玩家点击触发
var manual_attack_queued := false     # 手动模式下的待发普攻指令
var role_focus_target_uid := -1        # 玩家“攻”指令指定目标；不覆盖嘲讽/混乱与近战前排规则
var potions_left := 0                 # 治疗药剂
var potion_cd_ticks := 0              # 药剂 CD（8 秒一瓶，防连点误用）
var potion_effect_mult := 1.0
const POTION_CD := 8 * 30
## 药剂回复比例（占最大生命）。表现层「道具页」直接读它写详情，避免两处各写一份 0.35。
const POTION_HEAL_PCT := 0.35
var pet_bench_id := ""                # 替补宠物 id
var pet_swap_used := false
var enemy_scale := 1.0                # 层难度 ×(1+0.12N)
var pet_level := 1                    # 宠物等级随人物等级（v0 简化；有 pet_stats 快照时以快照为准）
var pet_stats: Dictionary = {}        # 局外宠物养成快照 {pid: {level, stat_mult, growth_mult}}
## 组建失败原因（空主题池等）：调用方据此拒绝开战，别让「一 tick 就判胜」的空战斗照发奖励
var setup_error := ""
## 世界主题规则（C 批，maps.json themes.<id>.rule）：纯表驱动，规则 id + params。
## 八个世界只差数值、玩法元素从第 1 个世界起就全见过，这是当前最大的「新鲜感缺口」。
var theme_id := ""
var theme_rule: Dictionary = {}
var rule_timer := 0        # 距下次触发的 tick 数（测试把它置 1 即可精确验证一次）
var _next_uid := 1
var _by_uid: Dictionary = {}

var campaign_profile: Dictionary = {}
var growth_perks: Dictionary = {}
const CampaignPressure := preload("res://src/world/CampaignPressure.gd")

var role_uid: int = 0
var companion_used: Dictionary = {} # 物种/特性 -> 一次标记或冷却截止 tick
var companion_participants: Array = []


# ---------- 组建 ----------
## ally_cfg: {role_id, level, traits[], active_pet, bench_pet, hp_override, potions}
## enemy_cfg: {theme, node_type("normal"/"elite"/"boss"), layer(1..3), enemy_mult,
##             solo, display_level}; 明雷按显示等级成长，历练按人物等级与层数成长。
##   enemy_mult 由调用方（苦行局）给，默认 1.0；模拟器不自己读表，保持内核无配置依赖。
func setup(seed: int, ally_cfg: Dictionary, enemy_cfg: Dictionary) -> void:
	# 同一模拟器可重用；上一场的单位、结果与错误不能泄漏到下一场。
	units.clear()
	_by_uid.clear()
	cast_queue.clear()
	last_cast.clear()
	events.clear()
	companion_used.clear()
	companion_participants.clear()
	_next_uid = 1
	role_uid = 0
	tick_count = 0
	finished = false
	result = ""
	setup_error = ""
	pet_bench_id = ""
	pet_swap_used = false
	potion_cd_ticks = 0
	rng.seed = seed
	campaign_profile = CampaignPressure.profile(String(enemy_cfg.get("world_map_id", "")))
	if enemy_cfg.get("difficulty_override") is Dictionary:
		campaign_profile = (enemy_cfg.difficulty_override as Dictionary).duplicate(true)
	role_focus_target_uid = -1
	manual_attack_queued = false
	theme_id = String(enemy_cfg.get("theme", "forest"))
	theme_rule = TableCache.theme_rule(theme_id)
	rule_timer = rule_interval_ticks()
	# 层难度系数读 nodes.json difficulty_scale_per_layer（禁止硬编码；与表说明「第N层 ×(1+0.12N)」同源）
	var per_layer: float = float(TableCache.nodes_config().get("difficulty_scale_per_layer", 0.12))
	enemy_scale = 1.0 + per_layer * float(int(enemy_cfg.get("layer", 1)))
	if bool(enemy_cfg.get("solo", false)) and int(enemy_cfg.get("display_level", 0)) > 0:
		enemy_scale = 1.0 + 0.16 * float(int(enemy_cfg.get("display_level", 1)) - 1)
	elif not (enemy_cfg.get("custom_mon") is Dictionary):
		# 历练保留层数差异，同时随角色等级成长，避免高等级反复秒杀初始怪。
		var per_level := maxf(0.0, float(TableCache.nodes_config().get("difficulty_scale_per_level", 0.08)))
		enemy_scale *= 1.0 + per_level * float(maxi(1, int(ally_cfg.get("level", 1))) - 1)
	enemy_scale *= maxf(0.1, float(enemy_cfg.get("enemy_mult", 1.0)))
	pet_level = maxi(1, int(ally_cfg.get("level", 1)))
	pet_stats = (ally_cfg.get("pet_stats", {}) as Dictionary).duplicate(true)
	_build_role(ally_cfg)
	if String(ally_cfg.get("active_pet", "")) != "":
		_build_pet(String(ally_cfg.active_pet), false)
	if String(ally_cfg.get("bench_pet", "")) != "":
		pet_bench_id = String(ally_cfg.bench_pet)
	potions_left = int(ally_cfg.get("potions", 0))
	potion_effect_mult = clampf(float(ally_cfg.get("potion_effect_mult",1.0)),0.9,1.1)
	var cm: Variant = enemy_cfg.get("custom_mon", null)
	if cm is Dictionary and not (cm as Dictionary).is_empty():
		_build_custom_mon(cm as Dictionary)   # 演武场等：不走怪物池，直接给对手数据
	else:
		_build_enemies(String(enemy_cfg.get("theme", "forest")),
			String(enemy_cfg.get("node_type", "normal")),
			String(enemy_cfg.get("lead_mon", "")), bool(enemy_cfg.get("solo", false)))
	if role_unit() == null or alive_units("enemy").is_empty():
		if setup_error.is_empty(): setup_error = "战斗配置无有效角色或敌人"
	if not setup_error.is_empty():
		finished = true
		result = "flee"
		emit({"t": "setup_error", "reason": setup_error})
		return
	# 地图机关造成的短暂护甲破绽在战斗创建时生效，计时走同一 tick 时钟。
	var opening_break: Dictionary = enemy_cfg.get("opening_def_break", {})
	var break_target := String(opening_break.get("monster_id", ""))
	if not break_target.is_empty():
		var break_ticks := clampi(int(opening_break.get("ticks", 0)), 1, 600)
		var break_pct := clampf(float(opening_break.get("pct", 0.0)), 0.0, 0.3)
		if break_pct > 0.0:
			for unit in units:
				if unit.side == "enemy" and String(unit.data.get("id", "")) == break_target:
					unit.add_buff("def_break", break_ticks, {"pct": break_pct,
						"stack_cap": 1})
	# 开场词条钩子
	for u in units:
		if u.traits != null:
			u.traits.on_battle_start(self, u)
	emit({"t": "ready", "units": units.map(func(u): return u.uid)})


func new_uid() -> int:
	_next_uid += 1
	return _next_uid - 1


func _build_role(cfg: Dictionary) -> void:
	var role := TableCache.get_role(String(cfg.get("role_id", "zs")))
	if role.is_empty():
		push_error("BattleSim 角色不存在：%s" % String(cfg.get("role_id", "")))
		return
	var stats := TableCache.role_stats(String(cfg.role_id), int(cfg.get("level", 1)))
	var ts := TraitSystem.new(cfg.get("traits", []))
	var gb0: Dictionary = cfg.get("growth", {}) if cfg.get("growth") is Dictionary else {}
	# 血上限走唯一口径（含局外成长；与 RunState.max_hp 共用，P1-6）
	stats.max_hp = TraitSystem.role_max_hp(String(cfg.role_id), int(cfg.get("level", 1)),
		cfg.get("traits", []), gb0)
	# 词条被动烧入其余基础属性
	stats.atk = int(float(stats.atk) * (1.0 + ts.passive_atk_pct()))
	stats.def = int(float(stats.def) * (1.0 + ts.passive_def_pct()))
	stats.spd = stats.spd * (1.0 + ts.passive_spd_pct())
	stats.crit += ts.passive_crit_add()
	# 局外养成加成（天赋/装备/坐骑/称号聚合，由 G.gd 计算后传入；缺省不影响）
	var gb: Dictionary = gb0
	growth_perks = {
		"crit_bleed": bool(gb.get("perk_crit_bleed", 0.0)),
		"last_stand": bool(gb.get("perk_last_stand", 0.0)),
		"quick_cast": bool(gb.get("perk_quick_cast", 0.0)),
	}
	if not gb.is_empty():
		stats.atk = int(float(stats.atk) * (1.0 + float(gb.get("atk_pct", 0.0))) + float(gb.get("atk_add", 0.0)))
		stats.def = int(float(stats.def) * (1.0 + float(gb.get("def_pct", 0.0))) + float(gb.get("def_add", 0.0)))
		stats.spd = stats.spd * (1.0 + float(gb.get("spd_pct", 0.0)))
		stats.crit += float(gb.get("crit_add", 0.0))
	role = role.duplicate(true)
	role["relic_break_damage_pct"] = float(gb.get("relic_break_damage_pct",0.0))
	var u := Combatant.new(new_uid(), "role", "ally", role)
	u.traits = ts
	u.base_max_hp = maxi(1, int(stats.max_hp))
	u.base_atk = maxi(1, int(stats.atk))
	u.base_def = maxi(0, int(stats.def))
	u.base_spd = stats.spd
	u.base_crit = clampf(stats.crit, 0.0, 0.95)
	u.crit_dmg = ts.crit_dmg_override() if ts.crit_dmg_override() > 0 else 1.5
	u.energy_gain_pct = ts.passive_energy_gain_pct() + float(gb.get("energy_pct", 0.0))
	u.cc_resist = clampf(ts.passive_cc_resist(), 0.0, 0.9)
	u.attack_range = String(role.get("attack_range", "melee"))
	u.row = Combatant.ROW_FRONT if u.attack_range == "melee" else Combatant.ROW_BACK
	u.col = 2
	u.hp = u.base_max_hp
	# HP 跨节点延续。哨兵口径：-1 = 无续血（满血开局）；>= 0 一律有效。
	# 0 必须钳到 1（濒危续战）：人物阵亡但宠物清场时，0 血开局等于必死——
	# 药剂救不回来（heal 拒绝治疗 hp<=0 的单位），下一个节点白给（A6）。
	var hp_override := int(cfg.get("hp_override", -1))
	if hp_override >= 0:
		u.hp = clampi(hp_override, 1, u.base_max_hp)
	var shield_pct := float(gb.get("relic_shield_pct",0.0))
	if shield_pct > 0.0: u.add_buff("shield", -1, {"pool":int(u.get_max_hp()*shield_pct)})
	role_uid = u.uid
	var allowed_v: Variant = cfg.get("unlocked_skills")
	var allowed: Array = allowed_v if allowed_v is Array else []
	var variants_v: Variant = cfg.get("skill_variants", {})
	var variants: Dictionary = variants_v if variants_v is Dictionary else {}
	for sid in role.get("skills", []):
		# unlocked_skills 只在主世界显式传入；其他玩法不传，继续保留完整五技。
		if cfg.has("unlocked_skills") and not allowed.has(String(sid)):
			continue
		var sd := TableCache.get_skill(String(sid))
		if not sd.is_empty():
			if variants.has(String(sid)) and variants[String(sid)] is Dictionary:
				sd = _apply_skill_variant(sd, variants[String(sid)] as Dictionary)
			# 伤害与辅助强度共享研习口径；始终深拷贝，不能污染缓存表。
			var slv := int((cfg.get("skill_levels", {}) as Dictionary).get(String(sid), 1))
			sd = SkillSystem.study_skill(sd, slv)
			u.skills.append({"id": String(sid), "def": sd, "cd_left": 0})
	_add_unit(u)


## 导师分支只改技能表副本。数值项集中在这里，按钮、AI 与真正结算读取同一份 def。
func _apply_skill_variant(base: Dictionary, mod: Dictionary) -> Dictionary:
	var out := base.duplicate(true)
	out["cost"] = maxi(0, int(out.get("cost", 0)) + int(mod.get("cost_delta", 0)))
	out["cd"] = maxf(0.5, float(out.get("cd", 0.0)) + float(mod.get("cd_delta", 0.0)))
	out["k"] = snappedf(float(out.get("k", 0.0)) * float(mod.get("k_mult", 1.0)), 0.001)
	var em := float(mod.get("effect_mult", 1.0))
	var effect_v: Variant = out.get("effect", {})
	if effect_v is Dictionary and not is_equal_approx(em, 1.0):
		var effect := effect_v as Dictionary
		for key in ["pct", "hp_pct", "atk_k"]:
			if effect.has(key):
				effect[key] = snappedf(float(effect[key]) * em, 0.001)
	return out


func _build_pet(pet_id: String, is_bench_swap: bool) -> void:
	var pet := TableCache.get_pet(pet_id)
	if pet.is_empty():
		push_warning("宠物不存在：%s" % pet_id)
		return
	var base: Dictionary = pet.get("base", {})
	# 宠物养成快照优先（升级/突破/资质），否则沿用人物等级（v0 简化）
	var growth: Dictionary = pet.get("growth", {})
	var ps: Dictionary = pet_stats.get(pet_id, {})
	if not companion_participants.has(pet_id): companion_participants.append(pet_id)
	var gl := float(int(ps.get("level", pet_level)) - 1)
	var gmult := float(ps.get("growth_mult", 1.0))
	var owner := unit_by_uid(role_uid)
	var stat_pct := 0.0
	if owner != null and owner.traits != null:
		stat_pct = owner.traits.pet_stat_pct()
	var mult := (1.0 + stat_pct) * float(ps.get("stat_mult", 1.0))
	var u := Combatant.new(new_uid(), "pet", "ally", pet)
	u.companion_traits = (ps.get("companion_traits",{}) as Dictionary).duplicate(true)
	u.base_max_hp = maxi(1, int((float(int(base.get("hp", 50))) + float(growth.get("hp", 0)) * gl * gmult) * mult))
	u.base_atk = maxi(1, int((float(int(base.get("atk", 10))) + float(growth.get("atk", 0)) * gl * gmult) * mult))
	u.base_def = maxi(0, int((float(int(base.get("def", 5))) + float(growth.get("def", 0)) * gl * gmult) * mult))
	u.base_spd = float(base.get("spd", 1.0))
	u.base_crit = 0.05
	u.attack_range = String(pet.get("attack_range", "melee"))
	u.row = Combatant.ROW_FRONT if u.attack_range == "melee" else Combatant.ROW_BACK
	u.col = 1
	u.hp = u.base_max_hp
	if is_bench_swap:
		u.deathproof_buff = true  # 换上获免死 1 次
	for sk in pet.get("skills", []):
		u.skills.append({"id": String(sk.get("id", "")), "def": sk, "cd_left": 0})
	_add_unit(u)


## maps.json 顶层 spawn 段（**不在主题条目里**）：编成数量表驱动（B4）
static func _spawn_cfg(node_type: String) -> Dictionary:
	var v: Variant = TableCache.maps_config().get("spawn", {})
	if v is Dictionary:
		var d := v as Dictionary
		var sub: Variant = d.get(node_type, {})
		return sub if sub is Dictionary else {}
	return {}


## BOSS 召唤上限（maps.json spawn.boss.summon_cap）
static func spawn_summon_cap() -> int:
	return maxi(1, int(_spawn_cfg("boss").get("summon_cap", 6)))


## 杂兵补位：前排 col1 → 后排 col2 → 后排 col1/3（与原本精英/BOSS 的补位一致）
func _spawn_adds(pick: Callable, n: int) -> void:
	var slots := [[Combatant.ROW_FRONT, 1], [Combatant.ROW_BACK, 2],
		[Combatant.ROW_BACK, 1], [Combatant.ROW_BACK, 3]]
	for i in n:
		var p: Array = slots[i % slots.size()]
		_spawn_monster(pick.call(), int(p[0]), int(p[1]))


## lead_mon：探索层撞到的那只怪（遇敌继承——撞谁谁领头，其余仍按池随机补位）
func _build_enemies(theme: String, node_type: String, lead_mon := "", solo := false) -> void:
	var tc := TableCache.theme_config(theme)
	var pool: Array = tc.get("monsters", [])
	if pool.is_empty():
		# 空池 = 组不出战斗：显式报错交给调用方拒绝开战，别再「一 tick 判胜还照发奖励」
		setup_error = "主题怪物池为空：%s" % theme
		push_error(setup_error)
		return
	var pick := func() -> String:
		return String(pool[rng.randi_range(0, pool.size() - 1)])
	# 主世界明雷是一只具体的地图怪：接触谁就与谁交战；历练编成保持原样。
	if solo and node_type in ["normal", "elite", "boss"]:
		_spawn_monster(lead_mon if lead_mon != "" else pick.call(),
			Combatant.ROW_FRONT, 2, 1.0, 1.0, node_type)
		return
	match node_type:
		"elite":
			var ec: Dictionary = TableCache.nodes_config().get("enemy", {})
			var hp_atk := float(ec.get("elite_hp_atk_mult", 1.8))
			var def_m := float(ec.get("elite_def_mult", 1.3))
			var sp := _spawn_cfg("elite")
			var n_elite := maxi(1, int(sp.get("elite_count", 1)))
			var e_cols := [2, 1]
			for i in n_elite:
				var elite := _spawn_monster(
					lead_mon if (i == 0 and lead_mon != "") else pick.call(),
					Combatant.ROW_FRONT, int(e_cols[i % e_cols.size()]), hp_atk, def_m, "elite")
				if elite != null:      # 怪物 id 失效时不再空引用（原代码直接 _apply_elite_affix(null)）
					_apply_elite_affix(elite)
			_spawn_adds(pick, int(sp.get("adds", 2)))
		"boss":
			var sp := _spawn_cfg("boss")
			var n_boss := maxi(1, int(sp.get("boss_count", 1)))
			for i in n_boss:
				_spawn_monster(String(tc.get("boss", "")), Combatant.ROW_FRONT,
					2 if i == 0 else 1, 1.0, 1.0, "boss")
			_spawn_adds(pick, int(sp.get("adds", 2)))
		_:
			var nc: Variant = _spawn_cfg("normal").get("count", [3, 4])
			var lo := 3
			var hi := 4
			if nc is Array and (nc as Array).size() >= 2:
				lo = int((nc as Array)[0])
				hi = maxi(lo, int((nc as Array)[1]))
			var n := rng.randi_range(lo, hi)
			var front_cols := [2, 1]
			var back_cols := [2, 1, 3]
			var fi := 0
			var bi := 0
			for i in n:
				var mon_id: String = (lead_mon if i == 0 and lead_mon != "" else pick.call())
				if i % 2 == 0 and fi < front_cols.size():
					_spawn_monster(mon_id, Combatant.ROW_FRONT, int(front_cols[fi]))
					fi += 1
				else:
					_spawn_monster(mon_id, Combatant.ROW_BACK, int(back_cols[bi % back_cols.size()]))
					bi += 1


## 演武场等模式的"自定义对手"：不走怪物池，直接给一份怪物数据（name/base/skills/tier）
func _build_custom_mon(d: Dictionary) -> void:
	var base: Dictionary = d.get("base", {})
	var u := Combatant.new(new_uid(), "monster", "enemy", d)
	u.base_max_hp = maxi(1, int(base.get("hp", 100)))
	u.base_atk = maxi(1, int(base.get("atk", 12)))
	u.base_def = maxi(0, int(base.get("def", 6)))
	u.base_spd = float(base.get("spd", 1.0))
	u.base_crit = 0.05
	u.attack_range = String(d.get("attack_range", "melee"))
	u.ai_type = String(d.get("ai", "boss"))
	u.row = Combatant.ROW_FRONT
	u.col = 2
	u.hp = u.base_max_hp
	for sk in d.get("skills", []):
		u.skills.append({"id": String(sk.get("id", "")), "def": sk, "cd_left": 0})
	_add_unit(u)


## tier 回写进 u.data（normal/elite/boss）：立绘高度 / 紫晕 / 名签三处表现全靠它（B4）。
## 坑：TableCache 返回的是**缓存引用**，必须 duplicate 后再写，否则这只精英会污染整张表。
func _spawn_monster(mon_id: String, row: int, col: int, hp_atk_mult := 1.0,
		def_mult := 1.0, tier := "normal") -> Combatant:
	var m := TableCache.get_monster(mon_id)
	if m.is_empty():
		push_warning("怪物不存在：%s" % mon_id)
		return null
	m = m.duplicate(true)
	m["tier"] = tier
	if not campaign_profile.is_empty() and tier == "boss":
		var phases: Array = m.get("phases", []).duplicate(true)
		for phase in CampaignPressure.extra_phases(mon_id): phases.append(phase)
		m["phases"] = phases
	var base: Dictionary = m.get("base", {})
	var u := Combatant.new(new_uid(), "monster", "enemy", m)
	u.base_max_hp = maxi(1, int(float(int(base.get("hp", 50))) * hp_atk_mult * enemy_scale))
	u.base_atk = maxi(1, int(float(int(base.get("atk", 10))) * hp_atk_mult * enemy_scale))
	u.base_def = maxi(0, int(float(int(base.get("def", 5))) * def_mult * enemy_scale))
	var prefix := "boss_" if tier == "boss" else ""
	u.base_max_hp = maxi(1,int(u.base_max_hp*float(campaign_profile.get(prefix+"hp",1.0))))
	u.base_atk = maxi(1,int(u.base_atk*float(campaign_profile.get(prefix+"atk",1.0))))
	u.base_def = maxi(0,int(u.base_def*float(campaign_profile.get(prefix+"def",1.0))))
	u.base_spd = float(base.get("spd", 1.0))
	u.base_crit = 0.05
	u.attack_range = String(m.get("attack_range", "melee"))
	u.ai_type = String(m.get("ai", "basic"))
	u.row = row
	u.col = col
	u.hp = u.base_max_hp
	for sk in m.get("skills", []):
		u.skills.append({"id": String(sk.get("id", "")), "def": sk, "cd_left": 0})
	_add_unit(u)
	return u


func _apply_elite_affix(elite: Combatant) -> void:
	match rng.randi_range(0, 3):
		0:
			elite.add_buff("lifesteal", -1, {"pct": 0.20})
		1:
			elite.add_buff("thorns", -1, {"pct": 0.15})
		2:
			elite.add_buff("spd_up", -1, {"pct": 0.30})
		3:
			elite.add_buff("def_up", -1, {"pct": 0.40})


func _add_unit(u: Combatant) -> void:
	units.append(u)
	_by_uid[u.uid] = u


# ---------- 查询 ----------
func unit_by_uid(uid: int) -> Combatant:
	return _by_uid.get(uid, null)


func alive_units(side: String) -> Array[Combatant]:
	var out: Array[Combatant] = []
	for u in units:
		if u.alive and u.side == side:
			out.append(u)
	return out


## 经典“攻”指令只改玩家普攻的选敌优先级，不另写伤害或攻速规则。
func set_role_focus_target(uid: int) -> bool:
	var target := unit_by_uid(uid)
	if target == null or not target.alive or target.side != "enemy":
		return false
	role_focus_target_uid = uid
	return true


func role_attack_ready() -> bool:
	var role := role_unit()
	if role == null or not role.alive or finished or not role.can_act():
		return false
	return role.attack_timer >= role.basic_threshold()


func trigger_manual_attack() -> String:
	if finished:
		return "finished"
	var role := role_unit()
	if role == null or not role.alive:
		return "dead"
	if not role.can_act():
		return "controlled"
	if role.attack_timer < role.basic_threshold():
		manual_attack_queued = true
		return "queued"
	manual_attack_queued = false
	role.attack_timer = 0
	role.do_basic_attack(self)
	return "attacked"


func has_boss() -> bool:
	for u in units:
		if u.alive and u.side == "enemy" and u.ai_type == "boss":
			return true
	return false


func role_unit() -> Combatant:
	return unit_by_uid(role_uid)


func emit(e: Dictionary) -> void:
	if record_events:
		events.append(e)


# ---------- 指令（玩家输入，经校验后入队） ----------
func cast_skill(uid: int, skill_id: String, target_uid := -1) -> bool:
	var u := unit_by_uid(uid)
	if u == null:
		return false
	# 必须从该单位的技能栏取最终 def：这里已经叠好技能书等级与导师分支。
	# 旧实现重新读 TableCache 原表，导致按钮施放时所有局外加成都被静默抹掉。
	var sd: Dictionary = {}
	for slot_v in u.skills:
		var slot := slot_v as Dictionary
		if String(slot.get("id", "")) == skill_id:
			sd = slot.get("def", {})
			break
	if sd.is_empty():
		return false
	if not SkillSystem.can_cast(self, u, sd):
		return false
	SkillSystem.enqueue_cast(self, u, sd, target_uid)
	return true


func use_potion() -> bool:
	if potions_left <= 0 or finished or potion_cd_ticks > 0:
		return false
	var role := role_unit()
	if role == null or not role.alive:
		return false
	# 满血喝药：直接拒绝，不扣瓶也不进 CD（地图侧早有拦截，战斗内漏了这条）
	if role.hp >= role.get_max_hp():
		return false
	potions_left -= 1
	potion_cd_ticks = POTION_CD
	var amt := DamageCalc.heal_amount(role.get_max_hp(), 0, POTION_HEAL_PCT * potion_effect_mult, 0.0)
	role.heal(amt, role, self)
	return true


func swap_pet() -> bool:
	if pet_bench_id.is_empty() or pet_swap_used or finished:
		return false
	# 当前出战宠退场（本局不可再上）
	for i in range(units.size() - 1, -1, -1):
		if units[i].kind == "pet" and units[i].side == "ally":
			emit({"t": "pet_leave", "uid": units[i].uid})
			_by_uid.erase(units[i].uid)
			units.remove_at(i)
	pet_swap_used = true
	_build_pet(pet_bench_id, true)
	emit({"t": "pet_enter", "id": pet_bench_id})
	return true


# ---------- 主循环（§2.1 一帧时序） ----------
func step() -> void:
	if finished:
		return
	# 0. 药剂 CD 计时（防连点误用）
	if potion_cd_ticks > 0:
		potion_cd_ticks -= 1
	# 1. BuffSystem.tick
	for u in units:
		if u.alive:
			u.tick_buffs(self)
	# 2. 施法队列推进（前摇）
	for i in range(cast_queue.size() - 1, -1, -1):
		var e: Dictionary = cast_queue[i]
		e.windup = int(e.windup) - 1
		if int(e.windup) <= 0:
			cast_queue.remove_at(i)
			SkillSystem.resolve_cast(self, e)
	# 3. 词条 on_tick
	for u in units:
		if u.alive and u.traits != null:
			u.traits.on_tick(self, u)
	# 4. 普攻计时 + CD 计时
	for u in units:
		if not u.alive:
			continue
		if u.kind == "role" and bool(growth_perks.get("last_stand", false)) \
				and not u.once_flags.has("growth_last_stand") \
				and float(u.hp) / float(maxi(u.get_max_hp(), 1)) <= 0.35:
			u.once_flags["growth_last_stand"] = true
			u.add_buff("shield", 5 * TICK_RATE, {"pool": maxi(1, int(u.get_max_hp() * 0.20))})
			emit({"t": "buff", "uid": u.uid, "buff": "shield"})
		for s in u.skills:
			if int(s.cd_left) > 0:
				s.cd_left = int(s.cd_left) - 1
		if u.can_act():
			var threshold := u.basic_threshold()
			if u.attack_timer < threshold:
				u.attack_timer += 1
			var hold_manual := u.kind == "role" and manual_basic_attack and not auto_mode
			if u.attack_timer >= threshold and (not hold_manual or manual_attack_queued):
				if u.kind == "role":
					manual_attack_queued = false
				u.attack_timer = 0
				u.do_basic_attack(self)
				# 宠物攻击触发主人共鸣词条
				if u.kind == "pet":
					var owner := role_unit()
					if owner != null and owner.traits != null:
						owner.traits.on_pet_hit(self, owner, u, 10)
	# 5. AI/托管指令
	for u in units:
		if not u.alive:
			continue
		if u.side == "enemy" or u.kind == "pet":
			MonsterAI.decide(self, u)
		elif auto_mode:
			MonsterAI.decide_auto(self, u)
	# 6. 世界主题规则（C 批）：周期类规则在这里 tick；揭示半径那条在 MapScene 侧生效
	_apply_theme_rule()
	# 6.5 首领阶段（P03）：只在单位数据表带 phases 时生效（历练首领没有 phases，行为不变）
	_apply_phases()
	# 7. 死亡/胜负判定
	tick_count += 1
	if alive_units("enemy").is_empty():
		finished = true
		result = "victory"
		emit({"t": "victory"})
	elif alive_units("ally").is_empty():
		finished = true
		result = "defeat"
		emit({"t": "defeat"})
	elif tick_count >= MAX_TICKS:
		# 到硬上限判「平局」：演武场据此不扣分；PVE 由 MapScene 显式按败处理（口径 D3）
		finished = true
		result = "draw"
		emit({"t": "timeout"})


## 跑完整场（headless 模拟/TTK 用）
func run_to_end() -> String:
	while not finished:
		step()
	return result


## 状态哈希（确定性对拍用）
func hash_state() -> int:
	var h := (tick_count * 31 + role_focus_target_uid + 1) % 2147483647
	for u in units:
		h = (h * 31 + u.uid * 1000003 + u.hp * 7919 + u.energy) % 2147483647
	return h


# ---------- 首领阶段（P03，表驱动） ----------
## 施加一个 buff 规格 {type, dur(秒, <=0 表永久), pct}。技能 after.self_buff 与首领阶段共用，
## 保证「破绽 / 硬直 / 加速」三条路径的时长与数值口径只有一处。
func apply_buff_spec(u: Combatant, spec: Dictionary) -> void:
	if u == null or not u.alive:
		return
	var t := String(spec.get("type", ""))
	if t.is_empty():
		return
	var dur := float(spec.get("dur", 0.0))
	var ticks := -1 if dur <= 0.0 else maxi(1, int(dur * float(TICK_RATE)))
	var val := {}
	var pct := float(spec.get("pct", 0.0))
	if pct != 0.0:
		val["pct"] = pct
	u.add_buff(t, ticks, val)
	emit({"t": "buff", "uid": u.uid, "buff": t, "dur": ticks})


## 首领阶段：血量跌破阈值时解锁技能 / 永久增益 / 自身状态，并广播 onphase 横幅事件。
## 只触发一次（记在 once_flags），阈值按整数血量比例判定，无随机 → 不影响历练与确定性对拍。
func _apply_phases() -> void:
	for u in units:
		if not u.alive or u.side != "enemy":
			continue
		var phases: Variant = u.data.get("phases")
		if not (phases is Array):
			continue
		var max_hp := maxi(1, u.get_max_hp())
		for ph in (phases as Array):
			if not (ph is Dictionary):
				continue
			var p := ph as Dictionary
			var flag := "phase_" + String(p.get("id", ""))
			if u.once_flags.has(flag):
				continue
			if float(u.hp) / float(max_hp) > float(p.get("hp_below", 0.0)):
				continue
			u.once_flags[flag] = true
			_enter_phase(u, p)


func _enter_phase(u: Combatant, p: Dictionary) -> void:
	# 解锁技能（同 id 已在技能表里就跳过，避免阶段重复加后技能栏出现两条同名）
	for sk in p.get("add_skills", []):
		if not (sk is Dictionary):
			continue
		var sid := String((sk as Dictionary).get("id", ""))
		var dup := false
		for s in u.skills:
			if String(s.get("id", "")) == sid:
				dup = true
				break
		if not dup and not sid.is_empty():
			u.skills.append({"id": sid, "def": sk, "cd_left": 0})
	# 永久增益（dur <= 0 → 永久；不随阶段回退）
	var buffs_v: Variant = p.get("buffs")
	if buffs_v is Dictionary:
		for k in (buffs_v as Dictionary):
			var spec: Variant = (buffs_v as Dictionary)[k]
			var d := (spec as Dictionary).duplicate() if spec is Dictionary else {}
			d["type"] = String(k)
			d["dur"] = 0.0
			apply_buff_spec(u, d)
	# 自身状态（碎碑硬直等）：走同一套施法后自身状态的口径
	var sb: Variant = p.get("self_buff")
	if sb is Dictionary:
		apply_buff_spec(u, sb as Dictionary)
	emit({"t": "phase", "uid": u.uid, "id": String(p.get("id", "")),
		"name": String(p.get("name", "")), "announce": String(p.get("announce", ""))})


## 死亡钩子（P05-C，表驱动）：单位阵亡后检查存活敌首领**已进入**的阶段里有没有 on_death，
## 命中死者 id 就执行该阶段的死后反应（例：失路兽「迷路低吼」召出的影狼先死 → 首领获得
## 4 秒破绽）。一条阶段钩子只触发一次；阶段未进入（once_flags 无 phase_<id>）不响应——
## 影狼在阶段前被别的途径召出来时不该白给破绽。
func notify_death(dead: Combatant) -> void:
	if dead == null or dead.side != "enemy" or dead.data.is_empty():
		return
	var mid := String(dead.data.get("id", ""))
	if mid.is_empty():
		return
	for u in units:
		if u == dead or not u.alive or u.side != "enemy":
			continue
		var phases: Variant = u.data.get("phases")
		if not (phases is Array):
			continue
		for ph in (phases as Array):
			if not (ph is Dictionary):
				continue
			var p := ph as Dictionary
			var pid := String(p.get("id", ""))
			if not u.once_flags.has("phase_" + pid):
				continue
			var od_v: Variant = p.get("on_death")
			if not (od_v is Dictionary):
				continue
			var od := od_v as Dictionary
			if String(od.get("mon_id", "")) != mid:
				continue
			var flag := "on_death_%s_%s" % [pid, mid]
			if u.once_flags.has(flag):
				continue
			u.once_flags[flag] = true
			var sb: Variant = od.get("self_buff")
			if sb is Dictionary:
				apply_buff_spec(u, sb as Dictionary)
			# 复用 phase 事件：表现层已有阶段横幅 + 破绽「绽」飘字两条通道，
			# 事件 id 加 _break 后缀只作区分，不参与任何状态判定。
			emit({"t": "phase", "uid": u.uid, "id": pid + "_break",
				"name": String(p.get("name", "")), "announce": String(od.get("announce", ""))})


# ---------- 世界主题规则（C 批，表驱动） ----------
func rule_params() -> Dictionary:
	var p: Variant = theme_rule.get("params", {})
	return p if p is Dictionary else {}


## 周期规则的间隔（tick）。0 / 负 = 该主题没有周期规则。
func rule_interval_ticks() -> int:
	return int(float(rule_params().get("interval", 0.0)) * float(TICK_RATE))


## 最大生命者（火山灼烧挑它；双向——敌我都可能中招，不是纯福利）
func highest_max_hp_unit() -> Combatant:
	var best: Combatant = null
	for u in units:
		if not u.alive:
			continue
		if best == null or u.get_max_hp() > best.get_max_hp():
			best = u
	return best


## 每条规则 = 一处 match 分支 + 一段表参数。后续世界照这个模板往里加。
func _apply_theme_rule() -> void:
	if theme_rule.is_empty():
		return
	var prm := rule_params()
	match String(theme_rule.get("id", "")):
		"volcano_burn":
			if not _rule_timer_tick():
				return
			var victim := highest_max_hp_unit()
			if victim == null:
				return
			var dmg := maxi(1, int(float(victim.get_max_hp()) * float(prm.get("hp_pct", 0.02))))
			# src 传 null：环境伤害**不占击杀归属**（on_kill 不会因灼烧收尾误记），
			# 也不触发受击钩子（与 A1 的「死人不再被奶回来」解耦）
			victim._direct_damage(dmg, null, self, true)
			emit({"t": "theme_rule", "rule": "volcano_burn", "uid": victim.uid, "amount": dmg})
		"snow_slip":
			if not _rule_timer_tick():
				return
			var dur := int(float(prm.get("dur", 2.0)) * float(TICK_RATE))
			var affected := alive_units("ally") + alive_units("enemy")
			for u in affected:
				u.add_buff("slow", dur, {"pct": prm.get("pct", 0.15)})
			emit({"t": "theme_rule", "rule": "snow_slip", "uid": -1, "amount": affected.size()})
		_:
			pass   # 其余规则不作用在战斗 tick 上（如深渊揭示半径在 MapScene 侧）


## 周期倒计时：到点返回 true 并重置。没配 interval 的规则永不触发。
func _rule_timer_tick() -> bool:
	if rule_interval_ticks() <= 0:
		return false
	rule_timer -= 1
	if rule_timer > 0:
		return false
	rule_timer = rule_interval_ticks()
	return true


# ---------- 战斗内动作：击退一排（岩龟冲撞等） ----------
func knock_back(t: Combatant) -> void:
	if t.row != Combatant.ROW_FRONT:
		return
	# 同列后排空位才退
	for u in units:
		if u.alive and u.side == t.side and u.row == Combatant.ROW_BACK and u.col == t.col:
			return
	t.row = Combatant.ROW_BACK
	emit({"t": "knockback", "uid": t.uid})


# ---------- 战斗召唤（BOSS 技能） ----------
func summon_monsters(caster: Combatant, mon_id: String, count: int, cap: int,
		row := Combatant.ROW_BACK) -> void:
	var enemies := alive_units("enemy")
	var n := mini(count, cap - enemies.size())
	if n <= 0:
		return
	var cols := [3, 1, 4, 0]
	var ci := 0
	for i in n:
		var summoned := _spawn_monster(mon_id, row, int(cols[ci % cols.size()]))
		if summoned != null:
			var scale := float(campaign_profile.get("summon_scale",1.0))
			summoned.base_max_hp = maxi(1,int(summoned.base_max_hp*scale))
			summoned.base_atk = maxi(1,int(summoned.base_atk*scale))
			summoned.base_def = maxi(0,int(summoned.base_def*scale))
			summoned.hp = summoned.base_max_hp
		ci += 1
	emit({"t": "summon", "uid": caster.uid, "count": n})

# Combatant.gd —— 战斗单位：属性/站位/能量/普攻/生命与 buff 容器（玩法文档 §1.3 §2.1 §2.3）
# 确定性铁律：时间全用整数 tick（1 tick = 1/30s），伤害全整数，随机全走 sim.rng。
class_name Combatant
extends RefCounted

const ROW_FRONT := 0
const ROW_BACK := 1
const MAX_ENERGY := 100            # 同 data/growth.json energy.max（编译期常量，改表须同步——UI 按静态访问）
const BASIC_INTERVAL_TICKS := 60   # 普攻基准 2.0s = 60 ticks（÷SPD 在 getter）；同 growth.json basic_attack_interval

var uid: int = 0
var kind: String = ""            # "role" / "monster" / "pet"
var side: String = ""            # "ally" / "enemy"
var name: String = ""
var data: Dictionary = {}        # 原始数据表行
var row: int = ROW_FRONT
var col: int = 2

# 基础属性（词条被动加成在构建时烧入 base_*；战斗中动态增益走 getter）
var base_max_hp: int = 1
var base_atk: int = 1
var base_def: int = 0
var base_spd: float = 1.0
var base_crit: float = 0.05
var crit_dmg: float = 1.5
var energy_gain_pct: float = 0.0   # 词条：能量获取加成
var cc_resist: float = 0.0         # 控制抗性（词条/怪物词条）

var hp: int = 1
var alive: bool = true
var energy: int = 0                # 仅 role 使用
var attack_range: String = "melee" # "melee" / "range"
var ai_type: String = "basic"      # 怪物 AI：basic / front / back / boss

var attack_timer: int = 0
var first_basic_done: bool = false # 词条"先发制人"
var rampage_stacks: int = 0        # 词条"越战越勇"
var once_flags: Dictionary = {}    # 词条一次性标记（如回光返照）
var deathproof_buff: bool = false  # 换宠免死
var traits: TraitSystem = null     # 仅我方 role 持有
var companion_traits: Dictionary = {} # 已训练特性的入场快照；老档为空

var buffs: Array[Dictionary] = []  # {type, dur(ticks, -1 永久), stacks, val}
var skills: Array[Dictionary] = [] # {id, def, cd_left(ticks)}


func _init(p_uid: int, p_kind: String, p_side: String, p_data: Dictionary) -> void:
	uid = p_uid
	kind = p_kind
	side = p_side
	data = p_data
	name = String(p_data.get("name", "单位"))


# ---------- 生效属性（buff + 动态词条合并） ----------
func get_max_hp() -> int:
	return base_max_hp


func get_atk() -> int:
	var pct := 0.0
	for b in buffs:
		match String(b.type):
			"atk_up": pct += float(b.val.get("pct", 0.0))
			"atk_down": pct -= float(b.val.get("pct", 0.0))
	if traits != null:
		pct += traits.dynamic_atk_pct(self)
	if kind == "monster" and ai_type == "boss" and (data.get("phases", []) as Array).is_empty() \
			and float(hp) / float(maxi(1, get_max_hp())) < 0.3:
		pct += 0.3  # BOSS 阶段狂暴
	return maxi(1, int(float(base_atk) * (1.0 + pct)))


func get_def() -> int:
	var pct := 0.0
	for b in buffs:
		match String(b.type):
			"def_up": pct += float(b.val.get("pct", 0.0))
			"def_break": pct -= float(b.val.get("pct", 0.0))
	return maxi(0, int(float(base_def) * (1.0 + pct)))


func get_spd() -> float:
	var pct := 0.0
	for b in buffs:
		match String(b.type):
			"spd_up": pct += float(b.val.get("pct", 0.0))
			"slow": pct -= float(b.val.get("pct", 0.0))
	if traits != null:
		pct += traits.dynamic_spd_pct(self)
	return maxf(0.3, base_spd * (1.0 + pct))


func get_crit() -> float:
	var add := 0.0
	for b in buffs:
		if String(b.type) == "crit_up":
			add += float(b.val.get("pct", 0.0))
	return clampf(base_crit + add, 0.0, 0.95)


func basic_threshold() -> int:
	return maxi(10, int(float(BASIC_INTERVAL_TICKS) / get_spd()))


# ---------- 状态查询 ----------
func is_controlled() -> bool:
	return has_buff("stun") or has_buff("fear")


func can_act() -> bool:
	return alive and not is_controlled()


func has_buff(type: String) -> bool:
	for b in buffs:
		if String(b.type) == type:
			return true
	return false


func get_buff(type: String) -> Dictionary:
	for b in buffs:
		if String(b.type) == type:
			return b
	return {}


func buff_pct_sum(type: String) -> float:
	var s := 0.0
	for b in buffs:
		if String(b.type) == type:
			s += float(b.val.get("pct", 0.0))
	return s


## 控制时长（秒 → tick）：倍率一律取**施加方**的 traits（A3）。
## 历史 bug：调用方传的是被控方（`t.cc_duration_ticks`），怪物没有 traits（恒 1.0），
## 「霜寒延长 / 控制流派 +30%」整条不生效，还会把自己被控的时间拉长。
func cc_duration_ticks(dur_s: float) -> int:
	var dur := dur_s
	if traits != null:
		dur *= 1.0 + traits.cc_dur_pct()
	return int(dur * 30.0)


# ---------- buff 生命周期 ----------
## 同类 buff 的数值合并口径（A8）：**逐键合并，绝不整包替换**。
## 坑：DoT 把浮点累积器 `acc` 存在 val 里（tick_buffs），整包替换会把已累积的部分清零。
## 口径：pool 累加（护盾可叠）/ atk·pct·stack_cap 取强 / acc 保留 / 其余（src_uid）取新。
static func _merge_buff_val(old: Dictionary, add: Dictionary) -> void:
	for k in add.keys():
		match String(k):
			"pool":
				old["pool"] = int(old.get("pool", 0)) + int(add[k])
			"atk":
				old["atk"] = maxi(int(old.get("atk", 0)), int(add[k]))
			"pct", "stack_cap":
				old[k] = maxf(float(old.get(k, 0.0)), float(add[k]))
			"acc":
				pass  # 累积器保留旧的，不能被重复施放清零
			_:
				old[k] = add[k]


func add_buff(type: String, dur_ticks: int, val: Dictionary = {}) -> void:
	var stack_add: int = int(val.get("stacks", 1))
	var stack_cap: int = int(val.get("stack_cap", 5))
	for b in buffs:
		if String(b.type) == type:
			# 同类刷新时长并叠层
			if dur_ticks < 0:
				b.dur = -1                                    # 新的永久 buff：提级为永久
			elif int(b.dur) >= 0:
				b.dur = maxi(int(b.dur), dur_ticks)           # 永久（dur<0）不被限时刷新改写
			# 层数上限一经写入即固定，后续只放宽：否则重创 3 层会被低层技能打回 1
			var cap: int = maxi(int(b.val.get("stack_cap", stack_cap)), stack_cap)
			b.val["stack_cap"] = cap
			b.stacks = mini(int(b.stacks) + stack_add, cap)
			_merge_buff_val(b.val, val)
			return
	var entry := {"type": type, "dur": dur_ticks, "stacks": mini(stack_add, stack_cap),
		"val": val.duplicate()}
	(entry["val"] as Dictionary)["stack_cap"] = stack_cap
	buffs.append(entry)


func remove_buff(type: String) -> void:
	for i in range(buffs.size() - 1, -1, -1):
		if String(buffs[i].type) == type:
			buffs.remove_at(i)


func dispel_debuffs() -> int:
	var removed := 0
	for i in range(buffs.size() - 1, -1, -1):
		var t := String(buffs[i].type)
		if t in ["bleed", "poison", "stun", "fear", "confusion", "slow", "def_break", "atk_down"]:
			buffs.remove_at(i)
			removed += 1
	return removed


func tick_buffs(sim: BattleSim) -> void:
	for i in range(buffs.size() - 1, -1, -1):
		var b: Dictionary = buffs[i]
		# 持续伤害：每 tick val.atk×pct/30（快照施放者 ATK）
		var t := String(b.type)
		if t == "bleed" or t == "poison":
			# 每秒 atk×pct×stacks：按 tick 浮点累积，acc≥1 才结算整数伤害（防小额毒被下限放大）
			var acc := float(b.val.get("acc", 0.0))
			acc += (float(int(b.val.get("atk", 1))) * float(b.val.get("pct", 0.0))
				* float(int(b.stacks)) / 30.0)
			if acc >= 1.0:
				var dot := int(acc)
				acc -= float(dot)
				# DoT 归属：伤害记到**施加者**头上（A2）。以前把 src 传成中毒者自己，
				# 击杀钩子会算成「自杀」，越战越勇 / 威吓 / 流血击杀回血整条失效
				var applier: Combatant = sim.unit_by_uid(int(b.val.get("src_uid", -1)))
				_direct_damage(dot, applier if applier != null else self, sim, true)
			b.val["acc"] = acc
		if int(b.dur) > 0:
			b.dur = int(b.dur) - 1
			if int(b.dur) == 0:
				buffs.remove_at(i)
				sim.emit({"t": "buff_end", "uid": uid, "buff": t})


# ---------- 伤害与治疗 ----------
## 直伤入口（dot/反伤走此路，不再触发受击钩子，防无限循环）
func _direct_damage(dmg: int, src: Combatant, sim: BattleSim, is_dot := false) -> int:
	if not alive or dmg <= 0:
		return 0
	if has_buff("invincible"):
		sim.emit({"t": "immune", "uid": uid})
		return 0
	var dealt := mini(hp, dmg)
	hp = maxi(0, hp - dmg)
	sim.emit({"t": "dmg", "src": src.uid if src != null else -1, "uid": uid,
		"amount": dealt, "crit": false, "dot": is_dot})
	if hp == 0:
		_on_lethal(sim, src)
	return dealt


## 正式伤害入口（技能/普攻；含潜伏减伤/护盾/反伤/吸血/受击词条钩子）
func take_damage(dmg: int, src: Combatant, sim: BattleSim, is_crit := false) -> int:
	if not alive or dmg <= 0:
		return 0
	if has_buff("invincible"):
		sim.emit({"t": "immune", "uid": uid})
		return 0
	var final := dmg
	if src != null and src.kind == "role" and String(data.get("tier", "")) == "boss" and has_buff("break_window"):
		final = int(final * (1.0 + float(src.data.get("relic_break_damage_pct", 0.0))))
	# 受方「受伤加深」（狂潮）下沉到唯一入口：以前只在技能路径结算，普攻不吃这条，
	# 双刃词条于是变成纯增益（SkillSystem 侧的同款应用已删，别再两处都算一遍）
	if traits != null:
		final = int(float(final) * (1.0 + traits.passive_dmg_taken_pct()))
	if has_buff("lurk"):
		final = maxi(1, final / 2)  # 潜伏：受击减半
	# 破绽（P03）：首领阶段/技能在自己身上留下的反击窗口，受击伤害按 pct 放大。
	# 纯查表 + 整数运算，无随机——同一份输入得到同一份结果（确定性护栏）。
	var break_pct := buff_pct_sum("break_window")
	if break_pct > 0.0:
		final = int(float(final) * (1.0 + break_pct))
	# 护盾吸收
	for i in range(buffs.size() - 1, -1, -1):
		var b: Dictionary = buffs[i]
		if String(b.type) == "shield":
			var pool: int = int(b.val.get("pool", 0))
			var absorb := mini(pool, final)
			b.val["pool"] = pool - absorb
			final -= absorb
			if int(b.val.get("pool", 0)) <= 0:
				buffs.remove_at(i)
			if final <= 0:
				sim.emit({"t": "shield_absorb", "uid": uid, "amount": absorb})
				return 0
	final = CompanionService.guard(sim,self,final,src)
	# 吸血、反伤与实效统计只认真正扣掉的生命，不能靠残血目标放大收益。
	final = mini(hp, final)
	hp = maxi(0, hp - final)
	sim.emit({"t": "dmg", "src": src.uid if src != null else -1, "uid": uid,
		"amount": final, "crit": is_crit, "dot": false})
	# 反伤（buff 与词条共用路径；反伤不再触发受击钩子）
	var reflect_pct := buff_pct_sum("thorns")
	if traits != null:
		reflect_pct += traits.reflect_pct()
	if src != null and src.alive and reflect_pct > 0.0:
		src._direct_damage(maxi(1, int(float(final) * reflect_pct)), self, sim)
	# 吸血：按攻击方自己的 lifesteal 结算、回攻击方（与上一段反伤的取向对称；
	# 历史 bug：曾读受击方的 buff，导致「打带吸血的敌人反而给玩家回血」）
	var lifesteal := (src.buff_pct_sum("lifesteal") if src != null else 0.0)
	if src != null and src.alive and lifesteal > 0.0:
		src.heal(maxi(1, int(float(final) * lifesteal)), self, sim)
	# 受击词条（以伤换伤回血）；on_behit 内部自带「已死则不再触发」护栏
	if traits != null:
		traits.on_behit(sim, self, src, final)
	if hp == 0:
		_on_lethal(sim, src)
	return final


## 致命伤结算。killer 用于驱动击杀钩子（A2）：宠物击杀记主人，环境伤害（null）与自伤不记归属。
func _on_lethal(sim: BattleSim, killer: Combatant) -> void:
	# 免死（换宠 buff）
	if deathproof_buff:
		deathproof_buff = false
		remove_buff("deathproof")
		hp = 1
		sim.emit({"t": "deathproof", "uid": uid})
		return
	# 词条：回光返照（每场 1 次）
	if traits != null and traits.prevent_death(sim, self):
		return
	alive = false
	hp = 0
	sim.emit({"t": "death", "uid": uid})
	# 死亡钩子（P05-C）：首领阶段表里的 on_death 以「死后反应」形式挂着（如影狼先死 → 首领破绽）。
	# 必须排在本单位的死亡事件之后：表现层先播倒地，再收阶段横幅。
	sim.notify_death(self)
	var k := killer
	if k != null and k.kind == "pet":
		k = sim.role_unit()      # 宠物击杀算主人的（主人流派的击杀收益才成立）
	if k == null or k == self or not k.alive or k.traits == null:
		return
	k.traits.on_kill(sim, k, self)


func heal(amount: int, src: Combatant, sim: BattleSim) -> int:
	# 死了就不再被奶回来（A1）：以伤换伤的回血曾排在死亡判定前，把致死伤「奶回去」→ 几乎无敌。
	# 回光返照 / 换宠免死都是直接写 hp，不走 heal，不受这条护栏影响。
	if not alive or hp <= 0 or amount <= 0:
		return 0
	var amt := amount
	if traits != null:
		amt = int(float(amt) * (1.0 + traits.heal_taken_pct()))
	amt = mini(amt, get_max_hp() - hp)
	if amt <= 0:
		return 0
	hp += amt
	sim.emit({"t": "heal", "src": src.uid if src != null else -1, "uid": uid, "amount": amt})
	return amt


func gain_energy(v: int) -> void:
	if kind != "role":
		return
	energy = mini(MAX_ENERGY, energy + maxi(0, int(float(v) * (1.0 + energy_gain_pct))))


# ---------- 普攻目标选择（§1.3 定稿：近战限前排；远程任意排默认最低血；嘲讽强制转火） ----------
func pick_basic_target(sim: BattleSim) -> Combatant:
	# 嘲讽优先
	var taunt_b := get_buff("taunt")
	if not taunt_b.is_empty():
		var taunter: Combatant = sim.unit_by_uid(int(taunt_b.val.get("src_uid", -1)))
		if taunter != null and taunter.alive:
			return taunter
	var enemies := sim.alive_units("enemy" if side == "ally" else "ally")
	if enemies.is_empty():
		return null
	# 混乱：随机目标（任意方，不含自身），伤害减半在结算处
	if has_buff("confusion"):
		var all: Array[Combatant] = []
		for u in sim.units:
			if u.alive and u != self:
				all.append(u)
		if all.is_empty():
			return null
		return all[sim.rng.randi_range(0, all.size() - 1)]
	# 玩家可以用经典“攻”指令集火；强控状态与原近战前排规则仍优先。
	if side == "ally" and kind == "role" and sim.role_focus_target_uid >= 0:
		var focus := sim.unit_by_uid(sim.role_focus_target_uid)
		if focus != null and focus.alive and focus.side == "enemy":
			var front_alive := _filter_row(enemies, ROW_FRONT)
			if attack_range != "melee" or focus.row == ROW_FRONT or front_alive.is_empty():
				return focus
	# 敌方 AI 目标规则（§2.5）；我方单位统一 basic 规则
	if side == "enemy":
		match ai_type:
			"front":
				var front := _filter_row(enemies, ROW_FRONT)
				if not front.is_empty():
					return front[0]
				return enemies[0]
			"back":
				var back := _filter_row(enemies, ROW_BACK)
				if not back.is_empty():
					return lowest_hp(back)
				return lowest_hp(enemies)
			_:  # basic / boss：最低血
				return lowest_hp(enemies)
	# 我方：近战限敌方前排（§1.3）；敌方前排全灭时战场推进，可攻击任意存活单位
	if attack_range == "melee":
		var front := _filter_row(enemies, ROW_FRONT)
		if front.is_empty():
			return lowest_hp(enemies)
		return lowest_hp(front)
	return lowest_hp(enemies)


func _filter_row(units: Array[Combatant], want_row: int) -> Array[Combatant]:
	var out: Array[Combatant] = []
	for u in units:
		if u.row == want_row:
			out.append(u)
	return out


func lowest_hp(units: Array[Combatant]) -> Combatant:
	var best: Combatant = units[0]
	for u in units:
		if u.hp < best.hp:
			best = u
	return best


# ---------- 普攻执行 ----------
func do_basic_attack(sim: BattleSim) -> void:
	var target := pick_basic_target(sim)
	if target == null:
		return
	first_basic_done = true
	var atk := get_atk()
	# 职业普攻系数只影响伤害，不抬高治疗/护盾或回能；镜影同样读取自身表值。
	var basic_atk := int(float(atk) * float(data.get("basic_attack_k", 1.0)))
	var dmg := DamageCalc.basic_damage(basic_atk, target.get_def())
	var crit_chance := get_crit()
	if traits != null:
		crit_chance += traits.crit_vs_full_hp_bonus(target)   # 弱点洞悉（P1-12）
	var is_crit := sim.rng.randf() < clampf(crit_chance, 0.0, 0.95)
	if is_crit:
		dmg = DamageCalc.crit_damage(dmg, crit_dmg)
	var halved := false
	if has_buff("confusion"):
		dmg = maxi(1, dmg / 2)
		halved = true
	# 词条：先发制人（本场首次普攻 ×表值 first_hit_k）
	if traits != null and not once_flags.has("first_strike"):
		once_flags["first_strike"] = true
		if traits.has_first_strike():
			dmg = int(float(dmg) * traits.first_strike_k())
	# 词条出手修正（处决者/碎冰等与技能共用——修「处决者只对技能生效」，P1-12）
	if traits != null:
		dmg = traits.modify_outgoing(self, target, dmg, false, false)
	sim.emit({"t": "basic", "src": uid, "uid": target.uid, "halved": halved})
	# 用 take_damage 的**返回值**（已减伤/已被盾吸收后的实数）喂命中钩子：
	# 以前喂的是未减伤的 dmg，打盾时饮血吸回来的血比实际造成的伤害还多
	var dealt := target.take_damage(dmg, self, sim, is_crit)
	if kind == "role" and is_crit and target.alive and bool(sim.growth_perks.get("crit_bleed", false)):
		target.add_buff("bleed", 3 * BattleSim.TICK_RATE,
			{"pct": 0.02, "atk": get_atk(), "stacks": 1, "stack_cap": 3, "src_uid": uid})
		sim.emit({"t": "proc", "src": uid, "uid": target.uid, "buff": "bleed"})
	# 怪物附带效果（毒/流血/减速按概率）
	if kind == "monster" and data.has("on_hit") and target.alive:
		var proc: Dictionary = data.on_hit
		if sim.rng.randf() < float(proc.get("chance", 0.0)):
			var ptype := String(proc.get("type", ""))
			var dur := int(float(proc.get("dur", 2.0)) * 30.0)
			match ptype:
				"poison", "bleed":
					target.add_buff(ptype, dur, {"pct": proc.get("pct", 0.03), "atk": atk,
						"stacks": 1, "stack_cap": 3, "src_uid": uid})
				"slow":
					target.add_buff("slow", dur, {"pct": proc.get("pct", 0.2)})
			sim.emit({"t": "proc", "src": uid, "uid": target.uid, "buff": ptype})
	# 词条命中钩子（普攻）
	if traits != null:
		traits.on_hit(sim, self, target, dealt, is_crit, false)
		if is_crit:
			traits.on_crit(sim, self, target)
	# 普攻 +表值能量（growth.json energy.per_basic_attack）
	var energy_cfg: Dictionary = TableCache.growth().get("energy", {})
	gain_energy(int(energy_cfg.get("per_basic_attack", 20)))

# SkillSystem.gd —— 技能施法：校验 → 前摇队列 → 结算（玩法文档 §1.4 §2.1）
class_name SkillSystem
extends RefCounted

const WINDUP_TICKS := 12        # 前摇 0.4s
const WINDUP_TICKS_ULT := 15    # 大招前摇 0.5s（cost≥60）


## 战斗与研习预览共用；只放大表中声明的强度，控制时长不随等级膨胀。
static func can_study(skill: Dictionary) -> bool:
	if float(skill.get("k", 0.0)) > 0.0:
		return true
	var effect: Dictionary = skill.get("effect", {}) if skill.get("effect") is Dictionary else {}
	var fields: Array = TableCache.skillbook_config().get("effect_scale_fields", {}).get(String(effect.get("type", "")), [])
	for field in fields:
		if float(effect.get(field, 0.0)) > 0.0:
			return true
	return false


static func study_skill(base: Dictionary, level: int) -> Dictionary:
	var out := base.duplicate(true)
	var cfg := TableCache.skillbook_config()
	var lv := clampi(level, 1, int(cfg.get("max_level", 10)))
	var mult := 1.0 + float(cfg.get("k_per_level", 0.05)) * float(lv - 1)
	out["k"] = snappedf(float(out.get("k", 0.0)) * mult, 0.001)
	if out.get("effect") is Dictionary:
		var effect := out["effect"] as Dictionary
		# 处决与受控增伤会替换 k，所以替换值也必须保留同一研习倍率。
		if effect.has("k_to"):
			effect["k_to"] = snappedf(float(effect["k_to"]) * mult, 0.001)
		var fields: Array = cfg.get("effect_scale_fields", {}).get(String(effect.get("type", "")), [])
		for field in fields:
			if effect.has(field):
				effect[field] = snappedf(float(effect[field]) * mult, 0.001)
	return out


## 施法校验：存活 / 未被控制 / CD 转好 / 能量足够 / 本单位不在施法中
static func can_cast(sim: BattleSim, caster: Combatant, skill: Dictionary) -> bool:
	if not caster.can_act():
		return false
	if String(skill.get("id", "")).is_empty():
		return false
	if bool(skill.get("once", false)) and caster.once_flags.has("skill_" + String(skill.get("id", ""))):
		return false
	# 施法中（前摇队列里已有本单位的招）不可再次入队——历史 bug：AI 每 tick 重复决策入队，
	# 一次施法刷出十几条 cast_start（提示/音效风暴），队列还被无效项塞满
	for q in sim.cast_queue:
		if int((q as Dictionary).get("uid", -1)) == caster.uid:
			return false
	for s in caster.skills:
		if String(s.def.get("id", "")) == String(skill.get("id", "")):
			if int(s.cd_left) > 0:
				return false
			break
	if caster.kind == "role" and int(skill.get("cost", 0)) > caster.energy:
		return false
	return true


## 入队（校验通过后调用）
static func enqueue_cast(sim: BattleSim, caster: Combatant, skill: Dictionary, target_uid := -1) -> void:
	var windup := WINDUP_TICKS_ULT if int(skill.get("cost", 0)) >= 60 else WINDUP_TICKS
	# 表驱动的 per-skill 前摇（秒）：慢招要让玩家**看得见**预兆（例：失路兽「嗅踪」2 秒，
	# 表现层按 cast_queue 剩余前摇画收缩环并逐帧倒数）。不给 windup 的照旧走 0.4/0.5 秒口径。
	var windup_sec := float(skill.get("windup", 0.0))
	if windup_sec > 0.0:
		windup = maxi(1, int(windup_sec * float(BattleSim.TICK_RATE)))
	if caster.traits != null:
		windup = maxi(6, int(float(windup) * (1.0 + caster.traits.passive_cd_pct() * 0.5)))
	if caster.kind == "role" and bool(sim.growth_perks.get("quick_cast", false)) \
			and int(skill.get("cost", 0)) <= 40:
		windup = maxi(6, int(float(windup) * 0.75))
	sim.cast_queue.append({"uid": caster.uid, "skill": skill, "windup": windup, "target_uid": target_uid})
	sim.emit({"t": "cast_start", "uid": caster.uid, "skill": String(skill.get("id", "")),
		"name": String(skill.get("name", ""))})


## 前摇到点结算
static func resolve_cast(sim: BattleSim, entry: Dictionary) -> void:
	var caster: Combatant = sim.unit_by_uid(int(entry.uid))
	if caster == null or not caster.alive:
		return
	var skill: Dictionary = entry.skill
	if not can_cast(sim, caster, skill):
		return
	# 全场已无敌人（只剩自方）时，伤害/控制类整招作废：不扣能量、不进 CD（历史 bug：空放照扣）
	var etype_pre := ""
	var effect_pre: Variant = skill.get("effect", {})
	if effect_pre is Dictionary:
		etype_pre = String((effect_pre as Dictionary).get("type", ""))
	if etype_pre != "heal" and etype_pre != "summon" and etype_pre != "cleanse":
		if sim.alive_units("enemy" if caster.side == "ally" else "ally").is_empty():
			return
	var chosen_ally := sim.unit_by_uid(int(entry.get("target_uid", -1)))
	if chosen_ally == null or not chosen_ally.alive or chosen_ally.side != caster.side:
		chosen_ally = null
	if etype_pre == "cleanse":
		if chosen_ally != null and _debuff_count(chosen_ally) == 0:
			return
		if chosen_ally == null and _cleanse_target(sim.alive_units(caster.side)) == null:
			return
	# 「满能量」快照必须在**扣能量之前**取（A4）：扣完再判恒为 false，
	# 上限 100、技能至少 20 费 → 超载（tr_energy_2）从未生效过
	var is_full_energy := caster.kind == "role" \
		and caster.energy >= Combatant.MAX_ENERGY \
		and int(skill.get("cost", 0)) > 0
	# 消耗与 CD
	if caster.kind == "role":
		caster.energy -= int(skill.get("cost", 0))
	var cd_ticks := int(float(skill.get("cd", 5)) * 30.0)
	if caster.traits != null:
		cd_ticks = maxi(15, int(float(cd_ticks) * (1.0 + caster.traits.passive_cd_pct())))
	for s in caster.skills:
		if String(s.def.get("id", "")) == String(skill.get("id", "")):
			s.cd_left = cd_ticks
			break
	# 连携检查（first 后 window 秒内施放 then）
	var combo := _check_combo(sim, caster, skill)
	sim.emit({"t": "cast", "uid": caster.uid, "skill": String(skill.get("id", "")),
		"name": String(skill.get("name", "")), "combo": combo.get("name", "")})
	_apply_skill(sim, caster, skill, combo, is_full_energy, chosen_ally)
	# 仅在实际结算后记一次性技能；前摇被控制打断仍可重新尝试。
	if bool(skill.get("once", false)):
		caster.once_flags["skill_" + String(skill.get("id", ""))] = true


static func _check_combo(sim: BattleSim, caster: Combatant, skill: Dictionary) -> Dictionary:
	var last: Dictionary = sim.last_cast.get(caster.uid, {})
	if last.is_empty():
		return {}
	var sid := String(skill.get("id", ""))
	if sid == String(last.get("skill_id", "")):
		return {}
	var last_id := String(last.get("skill_id", ""))
	var elapsed := sim.tick_count - int(last.get("tick", -99999))
	for c in TableCache.combos():
		if String(c.get("first", "")) == last_id and String(c.get("then", "")) == sid:
			if elapsed <= int(float(c.get("window", 5.0)) * 30.0):
				return c
	return {}


static func _apply_skill(sim: BattleSim, caster: Combatant, skill: Dictionary, combo: Dictionary,
		is_full_energy := false, chosen_ally: Combatant = null) -> void:
	# 记录连携窗口起点
	sim.last_cast[caster.uid] = {"skill_id": String(skill.get("id", "")), "tick": sim.tick_count}
	var target_type := String(skill.get("target", "enemy_single"))
	var effect_v: Variant = skill.get("effect", {})
	var effect: Dictionary = effect_v if effect_v is Dictionary else {}
	var k := float(skill.get("k", 0.0))
	var hits: int = maxi(1, int(skill.get("hits", 1)))

	# k 动态调整
	if not effect.is_empty():
		var et := String(effect.get("type", ""))
		if et == "execute_cond":
			var t0 := _primary_target(sim, caster, target_type)
			if t0 != null and float(t0.hp) / float(maxi(t0.get_max_hp(), 1)) < float(effect.get("hp_below", 0.3)):
				k = float(effect.get("k_to", k))
		elif et == "vs_controlled":
			var t0 := _primary_target(sim, caster, target_type)
			if t0 != null and (t0.has_buff("stun") or t0.has_buff("fear") or t0.has_buff("confusion")):
				k = float(effect.get("k_to", k))
	# 连携加成
	if not combo.is_empty():
		var ce: Dictionary = combo.get("effect", {})
		var cet := String(ce.get("type", ""))
		if cet == "k_bonus":
			k += float(ce.get("value", 0.0))
		elif cet == "vs_slowed_bonus":
			var t0 := _primary_target(sim, caster, target_type)
			if t0 != null and t0.has_buff("slow"):
				k *= 1.0 + float(ce.get("pct", 0.3))

	# 目标集合
	var etype := String(effect.get("type", ""))
	var targets := _pick_targets(sim, caster, target_type)
	if target_type == "ally_single" and chosen_ally != null:
		targets.clear()
		targets.append(chosen_ally)
	if etype == "cleanse":
		var cleanse_target := chosen_ally if chosen_ally != null else _cleanse_target(sim.alive_units(caster.side))
		targets.clear()
		if cleanse_target != null:
			targets.append(cleanse_target)
	var effective := 0
	var companion_effective := 0
	if targets.is_empty() and target_type != "ally_role" and etype != "heal" and etype != "summon" and etype != "cleanse":
		# 兜底：目标集合为空（敌方前排全灭 / 双方全远程编成）时改打最低血单体（与普攻同规则），
		# 避免 front_all 类技能空放还照扣能量与 CD
		var enemies := sim.alive_units("enemy" if caster.side == "ally" else "ally")
		if not enemies.is_empty():
			targets = [caster.lowest_hp(enemies)]
	if targets.is_empty() and etype != "heal" and etype != "summon":
		return
	match etype:
		"heal":
			effective = _apply_heal(sim, caster, skill, effect, targets, combo)
		"cleanse":
			for t in targets:
				var n := t.dispel_debuffs()
				companion_effective += n
				sim.emit({"t": "cleanse", "uid": t.uid, "count": n})
		"lurk":
			caster.add_buff("lurk", caster.cc_duration_ticks(float(effect.get("dur", 3.0))), {})
			companion_effective += 1
			sim.emit({"t": "buff", "uid": caster.uid, "buff": "lurk"})
		"taunt":
			var t := _primary_target(sim, caster, target_type)
			if t != null and sim.rng.randf() >= t.cc_resist:
				# 控制时长一律取**施加方** caster（A3）
				t.add_buff("taunt", caster.cc_duration_ticks(float(effect.get("dur", 3.0))),
					{"src_uid": caster.uid})
				companion_effective += 1
				sim.emit({"t": "buff", "uid": t.uid, "buff": "taunt"})
		"shield":
			for t in targets:
				var pool := int(float(t.get_max_hp()) * float(effect.get("hp_pct", 0.2)))
				t.add_buff("shield", -1, {"pool": pool})
				# 广播**合并后**的真实池子（A8）：重复施放以前只刷新时长不累加，
				# 却照扣能量与 CD，飘字还显示旧数值——玩家以为盾变多了其实没有
				var real := int(t.get_buff("shield").get("val", {}).get("pool", pool))
				sim.emit({"t": "shield_add", "uid": t.uid, "pool": real})
				effective += pool
		"atk_up":
			var dur_t := int(float(effect.get("dur", 5.0)) * 30.0)
			for t in targets:
				t.add_buff("atk_up", dur_t,
					{"pct": effect.get("pct", 0.2)})
				if String(skill.get("id", "")) == "fz_zhudao":
					t.add_buff("spd_up", dur_t, {"pct": float(effect.get("spd_pct", 0.18))})
				companion_effective += 1
				sim.emit({"t": "buff", "uid": t.uid, "buff": "atk_up"})
			if String(skill.get("id", "")) == "fz_zhudao":
				var foes := sim.alive_units("enemy" if caster.side == "ally" else "ally")
				if not foes.is_empty():
					var smite_target := caster.lowest_hp(foes)
					var smite_raw := DamageCalc.basic_damage(int(float(caster.get_atk()) * float(effect.get("smite_k", 1.45))), smite_target.get_def())
					effective += smite_target.take_damage(maxi(1, smite_raw), caster, sim, false)
		"invincible_heal":
			for t in targets:
				t.add_buff("invincible", int(float(effect.get("dur", 1.5)) * 30.0), {})
				companion_effective += 1
				var amt := DamageCalc.heal_amount(t.get_max_hp(), caster.get_atk(),
					float(effect.get("hp_pct", 0.08)), 0.0)
				var ce: Dictionary = combo.get("effect", {})
				if String(ce.get("type", "")) == "heal_bonus":
					amt = int(float(amt) * (1.0 + float(ce.get("pct", 0.3))))
				effective += t.heal(amt, caster, sim)
				sim.emit({"t": "buff", "uid": t.uid, "buff": "invincible"})
		"fear":
			var t := _primary_target(sim, caster, target_type)
			if t != null and sim.rng.randf() >= t.cc_resist:
				t.add_buff("fear", caster.cc_duration_ticks(float(effect.get("dur", 1.5))), {})
				companion_effective += 1
				sim.emit({"t": "buff", "uid": t.uid, "buff": "fear"})
		"stun":
			var t := _primary_target(sim, caster, target_type)
			if t != null and sim.rng.randf() >= t.cc_resist:
				t.add_buff("stun", caster.cc_duration_ticks(float(effect.get("dur", 1.2))), {})
				companion_effective += 1
				sim.emit({"t": "buff", "uid": t.uid, "buff": "stun"})
		"summon":
			var mon_id := String(skill.get("summon", ""))
			var count := int(skill.get("summon_count", 2))
			sim.summon_monsters(caster, mon_id, count,
				int(skill.get("summon_cap", BattleSim.spawn_summon_cap())),
				Combatant.ROW_FRONT if String(skill.get("summon_row", "back")) == "front" else Combatant.ROW_BACK)
		_:
			effective = _apply_damage(sim, caster, skill, k, hits, targets, effect, combo, is_full_energy)
	# 施法后的自身状态（P03）：首领技「打完露出破绽」这类代价写在数据表里，不塞进每个技能分支。
	# after.self_buff = {type, dur, pct}（例：break_window 破绽 4 秒、受伤 +35%）。
	var after_v: Variant = skill.get("after")
	if after_v is Dictionary:
		var sb: Variant = (after_v as Dictionary).get("self_buff")
		if sb is Dictionary:
			sim.apply_buff_spec(caster, sb as Dictionary)
	# P05-D 熟练只认真实效果：命中造成伤害、实际回复生命或真正加上护盾。
	# 空放、满血治疗、能量不足和被取消的前摇都不会发这条事件。
	if caster.kind == "role" and effective > 0:
		sim.emit({"t": "skill_effective", "uid": caster.uid,
			"skill": String(skill.get("id", "")), "amount": effective})
	# 后续授业接受成功的增益/控制与清除负面；独立事件保留原导师实效口径。
	if caster.kind == "role" and maxi(effective, companion_effective) > 0:
		sim.emit({"t": "curriculum_effective", "uid": caster.uid,
			"skill": String(skill.get("id", "")), "amount": maxi(effective, companion_effective)})
	CompanionService.on_skill(sim,caster,skill,maxi(effective,companion_effective),effective)


static func _apply_damage(sim: BattleSim, caster: Combatant, skill: Dictionary, k: float,
		hits: int, targets: Array[Combatant], effect: Dictionary, combo: Dictionary,
		is_full_energy := false) -> int:
	var total := 0
	for h in hits:
		var hit_targets := targets
		# 随机目标：每段独立随机
		if String(skill.get("target", "")) == "enemy_random":
			var all := sim.alive_units("enemy" if caster.side == "ally" else "ally")
			if all.is_empty():
				break
			hit_targets = [all[sim.rng.randi_range(0, all.size() - 1)]]
		for t in hit_targets:
			if not t.alive:
				continue
			var dmg := DamageCalc.basic_damage(int(float(caster.get_atk()) * k), t.get_def())
			# 无视防御（夺魄）
			if String(effect.get("type", "")) == "def_pierce":
				dmg = DamageCalc.basic_damage(int(float(caster.get_atk()) * k),
					int(float(t.get_def()) * (1.0 - float(effect.get("pct", 0.5)))))
			var crit_chance := caster.get_crit()
			if caster.traits != null:
				crit_chance += caster.traits.crit_vs_full_hp_bonus(t)   # 弱点洞悉（P1-12）
			var is_crit := sim.rng.randf() < clampf(crit_chance, 0.0, 0.95)
			if is_crit:
				dmg = DamageCalc.crit_damage(dmg, caster.crit_dmg)
			# 词条修正（凝神/处决/碎冰/超载）
			# 注：受方「受伤加深」（狂潮）已下沉到 Combatant.take_damage 统一入口，
			# 这里再算一遍就会double counting（普攻路径以前也整条漏掉）
			if caster.traits != null:
				dmg = caster.traits.modify_skill_dmg(caster, t, dmg, is_full_energy)
			var dealt := t.take_damage(dmg, caster, sim, is_crit)
			total += dealt
			if caster.traits != null:
				caster.traits.on_hit(sim, caster, t, dealt, is_crit, true)
				if is_crit:
					caster.traits.on_crit(sim, caster, t)
			# 汲取（亡灵君王）：造成伤害的 50% 回复自身
			if String(effect.get("type", "")) == "lifesteal":
				caster.heal(maxi(1, int(float(dealt) * float(effect.get("pct", 0.5)))), caster, sim)
			# 技能附加 dot（宠物技能）
			var add_type := String(effect.get("apply", effect.get("type", "")))
			if add_type in ["bleed", "poison"]:
				var cap: int = int(effect.get("stack", 1)) + (caster.traits.bleed_stack_cap_add() if caster.traits != null else 0)
				var pct := float(effect.get("pct", 0.03))
				if caster.traits != null:
					pct *= 1.0 + caster.traits.bleed_dmg_pct()
				t.add_buff(add_type, int(float(effect.get("dur", 4.0)) * 30.0),
					{"pct": pct, "atk": caster.get_atk(), "stacks": 1, "stack_cap": maxi(1, cap),
						"src_uid": caster.uid})
			elif add_type == "slow":
				t.add_buff("slow", int(float(effect.get("dur", 3.0)) * 30.0),
					{"pct": effect.get("pct", 0.2)})
			elif add_type == "def_down":
				# 破阵 / 贯甲：DEF -pct%（A5）。skills.json 写的是 def_down，
				# 而减防 buff 的实体名是 def_break（已在驱散白名单与状态条里）
				t.add_buff("def_break", int(float(effect.get("dur", 5.0)) * 30.0),
					{"pct": effect.get("pct", 0.2), "src_uid": caster.uid})
				sim.emit({"t": "buff", "uid": t.uid, "buff": "def_break"})
			# 击退一排（岩龟冲撞）：目标从前排压到后排
			if String(effect.get("type", "")) == "knockback_row" and t.row == Combatant.ROW_FRONT:
				sim.knock_back(t)
	# 词条：技能施放钩子（能量导管）
	if caster.traits != null and total > 0:
		caster.traits.on_skill_cast(sim, caster, total)
	return total


static func _apply_heal(sim: BattleSim, caster: Combatant, skill: Dictionary,
		effect: Dictionary, targets: Array[Combatant], combo: Dictionary) -> int:
	var hp_pct := float(effect.get("hp_pct", 0.1))
	var atk_k := float(effect.get("atk_k", 0.0))
	var ce: Dictionary = combo.get("effect", {})
	if String(ce.get("type", "")) == "heal_bonus":
		hp_pct *= 1.0 + float(ce.get("pct", 0.3))
		atk_k *= 1.0 + float(ce.get("pct", 0.3))
	var total := 0
	for t in targets:
		var amt := DamageCalc.heal_amount(t.get_max_hp(), caster.get_atk(), hp_pct, atk_k)
		total += t.heal(amt, caster, sim)
	return total


static func _pick_targets(sim: BattleSim, caster: Combatant, target_type: String) -> Array[Combatant]:
	var out: Array[Combatant] = []
	var enemies := sim.alive_units("enemy" if caster.side == "ally" else "ally")
	var allies := sim.alive_units(caster.side)
	match target_type:
		"enemy_single":
			var t := caster.pick_basic_target(sim)
			if t != null:
				out.append(t)
		"enemy_front_all":
			for e in enemies:
				if e.row == Combatant.ROW_FRONT:
					out.append(e)
		"enemy_back_single":
			var best: Combatant = null
			for e in enemies:
				if e.row == Combatant.ROW_BACK and (best == null or e.hp < best.hp):
					best = e
			if best == null and not enemies.is_empty():
				best = caster.lowest_hp(enemies)
			if best != null:
				out.append(best)
		"enemy_all":
			out = enemies
		"enemy_random":
			var t := caster.pick_basic_target(sim)
			if t != null:
				out.append(t)
		"ally_single":
			out.append(_heal_target(caster, allies))
		"ally_role":
			var role := sim.role_unit()
			if role != null and role.alive and role.side == caster.side:
				out.append(role)
		"ally_all":
			out = allies
		"self":
			out.append(caster)
	return out


static func _heal_target(caster: Combatant, allies: Array[Combatant]) -> Combatant:
	var best: Combatant = allies[0]
	for a in allies:
		if float(a.hp) / float(maxi(a.get_max_hp(), 1)) < float(best.hp) / float(maxi(best.get_max_hp(), 1)):
			best = a
	return best


static func _cleanse_target(allies: Array[Combatant]) -> Combatant:
	var best: Combatant = null
	var best_count := 0
	for ally in allies:
		var count := _debuff_count(ally)
		if count > best_count:
			best = ally
			best_count = count
	return best


static func _debuff_count(ally: Combatant) -> int:
	var count := 0
	for debuff in ["bleed", "poison", "slow", "def_break", "fear", "stun", "confusion", "atk_down"]:
		if ally.has_buff(debuff):
			count += 1
	return count


static func _primary_target(sim: BattleSim, caster: Combatant, target_type: String) -> Combatant:
	var targets := _pick_targets(sim, caster, target_type)
	if targets.is_empty():
		return null
	return targets[0]

